export const themeKey='offmenu-color-theme';
export function normalizePreference(value){return ['light','dark','system'].includes(value)?value:'system';}
export function resolveTheme(preference,systemDark=false){return preference==='dark'||(preference==='system'&&systemDark)?'dark':'light';}
export function loadPreference(getStorage){try{return normalizePreference(getStorage().getItem(themeKey));}catch{return 'system';}}
export function initTheme({doc=document,getStorage=()=>localStorage,getMedia=()=>matchMedia('(prefers-color-scheme: dark)')}={}){let media;try{media=getMedia();}catch{media={matches:false};}let preference=loadPreference(getStorage);const select=doc.getElementById('theme-select');function apply(){const theme=resolveTheme(preference,!!media.matches);doc.documentElement.dataset.theme=theme;doc.documentElement.style.colorScheme=theme;if(select)select.value=preference;return theme;}apply();if(select)select.onchange=()=>{preference=normalizePreference(select.value);try{getStorage().setItem(themeKey,preference);}catch{}apply();};const listener=()=>{if(preference==='system')apply();};if(media.addEventListener)media.addEventListener('change',listener);else if(media.addListener)media.addListener(listener);return{apply,setPreference(value){preference=normalizePreference(value);try{getStorage().setItem(themeKey,preference);}catch{}return apply();},get preference(){return preference;}};}
